insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '60a95e23-a3a2-4e29-b138-fcf5e2ac398d', id, '425.5.2', 'Lap splices of deformed bars in tension', 'Tension lap splices are Class A (1.0 ld) or Class B (1.3 ld), never less than 300 mm. Class B is the default unless the provided steel is at least twice the required steel and no more than half the bars are spliced within the lap length.', '{"aci_equivalent":"ACI 318-14 §25.5.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '6419620a-2e79-4f86-bff0-f2e83335848a', id, '426.5.6', 'Construction, contraction and isolation joints', 'Joints are located where they least impair strength: in floors, within the middle third of slab, beam and girder spans; in girders, offset from intersecting beams by at least twice the beam width. Surfaces are cleaned and laitance removed, and the joint is wetted (no standing water) before the next pour. Beams and slabs are cast together unless the drawings show otherwise.', '{"aci_equivalent":"ACI 318-14 §26.5.6"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '04d41ff5-0afd-4b70-ac7c-593e26460a97', id, '418.6.3', 'Special moment frame beams: longitudinal reinforcement', 'In special moment frame beams, lap splices of longitudinal bars must be enclosed by hoops or spirals over the splice length, and are not allowed inside joints, within 2h of the joint face, or where analysis shows flexural yielding.', '{"aci_equivalent":"ACI 318-14 §18.6.3"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '1158665e-2e0e-473e-8b16-7f92d84d8bb8', id, '418.7.4', 'Special moment frame columns: longitudinal reinforcement', 'In special moment frame columns, lap splices are only allowed within the center half of the member length. They are designed as tension lap splices and enclosed by the confinement reinforcement of 418.7.5.2–418.7.5.3.', '{"aci_equivalent":"ACI 318-14 §18.7.4"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select 'faa7a31b-fc11-4477-82b1-6ba28bf4b631', id, '418.7.5', 'Special moment frame columns: transverse reinforcement', 'Confinement length lo at each end is the largest of: column depth h, 1/6 of clear height, and 450 mm. Hoop spacing within lo is the smallest of: 1/4 of the least column dimension, 6 × the smallest longitudinal bar diameter, and so = 100 + (350 − hx)/3 mm, with so between 100 and 150 mm. Outside lo, spacing is ≤ 6db and ≤ 150 mm.', '{"aci_equivalent":"ACI 318-14 §18.7.5"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select 'fbf14d2c-2c17-4bc4-8ce3-6daf40ecbd14', id, '418.6.4', 'Special moment frame beams: transverse reinforcement', 'Hoops are required over 2h from the face of each supporting column (and wherever yielding may occur). The first hoop is placed ≤ 50 mm from the column face. Spacing in the hoop zone is the smallest of d/4, 6 × the smallest main bar diameter, and 150 mm. Elsewhere, stirrups with seismic hooks at ≤ d/2.', '{"aci_equivalent":"ACI 318-14 §18.6.4"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '54554dc5-f5b9-411b-a6ee-e5f15a4e360f', id, '420.6.1', 'Specified concrete cover', 'Minimum specified cover for cast-in-place nonprestressed concrete depends on exposure and member type. It is measured from the concrete surface to the outermost steel (usually the tie or stirrup), not to the main bar.', '{"aci_equivalent":"ACI 318-14 §20.6.1"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select 'd4b0cc6e-7cfd-41e0-a768-4010725140f5', id, '425.2', 'Minimum spacing of reinforcement', 'Clear spacing between parallel bars in a layer is at least the largest of 25 mm, db, and 4/3 of the maximum aggregate size. Bars in upper layers sit directly above lower ones, with ≥ 25 mm clear between layers. In columns, clear spacing between longitudinal bars is at least the largest of 40 mm, 1.5db, and 4/3 of the aggregate size.', '{"aci_equivalent":"ACI 318-14 §25.2"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '05457815-d96c-420c-8cd8-d8dba2a4107c', id, '425.3', 'Standard hooks, seismic hooks, crossties and bend diameters', 'Hook geometry (bend angle, straight extension, minimum inside bend diameter) for development hooks and for stirrups, ties and hoops. Seismic hooks are 135° (90° allowed for circular hoops) with an extension of at least 6db or 75 mm.', '{"aci_equivalent":"ACI 318-14 §25.3"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '1df11ba7-6a76-4960-b1c9-acb583bcf16b', id, '426.5.3', 'Curing', 'Concrete (other than high-early-strength) is kept above 10 °C and in a moist condition for at least the first 7 days after placement. High-early-strength concrete needs at least 3 days, unless accelerated curing is used.', '{"aci_equivalent":"ACI 318-14 §26.5.3"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.code_clauses (id, code_document_id, section_no, title, summary, limits) select '85509cad-14f7-4a01-8a7e-597da7dcad2a', id, '426.12', 'Evaluation and acceptance of concrete', 'Strength test frequency and acceptance criteria for standard-cured cylinders. A strength test is the average of at least two 150×300 mm or three 100×200 mm cylinders tested at the specified age (usually 28 days).', '{"aci_equivalent":"ACI 318-14 §26.12"}'::jsonb from public.code_documents where short_name = 'NSCP' and edition = '2015 (7th ed.)';
insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'c59e69de-084a-4a23-bc04-318c90f201c9', 'practice', 'Lap splice zones: continuous slabs', 'lap-splice-zones-continuous-slabs', id, 'Where to lap top and bottom slab bars in a continuous slab span.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('0a3476a5-d095-4b0d-8850-5375027beac8', 'c59e69de-084a-4a23-bc04-318c90f201c9', 1, '{"sections":[{"kind":"safe","heading":"Safe to splice","items":["Top bars: middle 0.4Ln, where top tension is lowest","Bottom bars: near the supports, within about 0.3Ln of each face"]},{"kind":"avoid","heading":"Avoid","items":["Top bars over the supports: highest negative moment","Bottom bars at midspan: highest positive moment"]},{"kind":"list","heading":"Terms","items":["Ln: clear span, face to face of supports","ld: development length of the bar in tension","Class B lap: 1.3 ld, not less than 300 mm"]},{"kind":"list","heading":"Site checklist","items":["Lap length matches the plans (default Class B)","Splices staggered, not all bars lapped at one section","Laps tied at both ends and the middle","Splice locations follow the structural drawings when they are shown"]},{"kind":"text","heading":"Note","text":"The 0.3 / 0.4 / 0.3 split is a common site rule for uniformly loaded continuous slabs, based on the moment diagram. The code''s general principle is to splice away from points of maximum stress. Cantilevers and unusual loading need their own zones from the designer. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"span","member":"slab","support":"beam","bands":"top-bottom","zones":[{"w":0.3,"top":"avoid","bottom":"safe"},{"w":0.4,"top":"safe","bottom":"avoid"},{"w":0.3,"top":"avoid","bottom":"safe"}],"dims":["0.3Ln","0.4Ln","0.3Ln"],"spanLabel":"Ln = clear span, face to face of supports","lap":[{"at":0.5,"band":"top"},{"at":0.14,"band":"bottom"},{"at":0.86,"band":"bottom"}],"diagram":"moment-continuous","caption":"Continuous slab: splice zones for top and bottom bars"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
insert into public.entry_clause_refs (entry_id, clause_id, note) values ('c59e69de-084a-4a23-bc04-318c90f201c9', '60a95e23-a3a2-4e29-b138-fcf5e2ac398d', 'Class B length · ACI 318-14 §25.5.2');
insert into public.entry_tags (entry_id, tag_id) select 'c59e69de-084a-4a23-bc04-318c90f201c9', id from public.tags where slug = 'slab';
