insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('62453dd2-92a7-42a7-b51e-efd86f8c04e7', '7c7739dc-fe5f-46a0-b9ea-1d7bc054f1fb', 1, '{"sections":[{"kind":"safe","heading":"Safe to splice","items":["Top bars: middle third of the span","Bottom bars: between 2h from the column face and the middle third","Every lap fully enclosed by hoops along its length"]},{"kind":"avoid","heading":"Avoid (not permitted in SMF)","items":["Any lap inside the beam-column joint","Any lap within 2h of the column face","Any lap where the analysis shows flexural yielding (plastic hinges)"]},{"kind":"list","heading":"Site checklist","items":["Mark 2h from each column face on the formwork before tying","Hoops at the specified spacing over the full lap length","Bottom bar laps not bunched at one section"]},{"kind":"text","heading":"Note","text":"For non-seismic (ordinary) frames the code limits are looser, so follow the design drawings. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"span","member":"beam","support":"column","bands":"top-bottom","zones":[{"w":0.12,"top":"avoid","bottom":"avoid"},{"w":0.21,"top":"avoid","bottom":"safe"},{"w":0.34,"top":"safe","bottom":"avoid"},{"w":0.21,"top":"avoid","bottom":"safe"},{"w":0.12,"top":"avoid","bottom":"avoid"}],"dims":["2h","","≈ Ln/3","","2h"],"spanLabel":"Ln = clear span, face to face of columns · h = beam depth","lap":[{"at":0.5,"band":"top"},{"at":0.22,"band":"bottom"},{"at":0.78,"band":"bottom"}],"diagram":"moment-continuous","caption":"SMF beam: no-splice zones within 2h of each column face"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
