insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('b4efd4e1-de59-495a-96b3-83fd6bbb57b1', '335d8d1a-30a2-4af1-983e-f6926545b024', 1, '{"sections":[{"kind":"safe","heading":"Safe to splice","items":["Within the center half of the clear column height","Designed as a tension lap splice","Enclosed by confinement hoops over the lap"]},{"kind":"avoid","heading":"Avoid","items":["Lapping right above the floor slab: a common site habit, but not allowed in SMF columns","Laps inside the end confinement regions"]},{"kind":"list","heading":"Site checklist","items":["Order column bars long enough to reach the center half of the next storey","Stagger mechanical couplers if used instead of laps","Check hoop spacing along the lap"]},{"kind":"text","heading":"Note","text":"Splicing just above the floor is acceptable only where the design does not require special moment frame detailing, so follow the plans. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"column","hoops":"uniform","zones":[{"h":0.25,"status":"avoid","label":"end region"},{"h":0.5,"status":"safe","label":"center half"},{"h":0.25,"status":"avoid","label":"end region"}],"dims":["¼ Lu","½ Lu","¼ Lu"],"lap":{"from":0.35,"to":0.6},"caption":"SMF column: lap splices only within the center half"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
