insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('b1cc61d2-62ec-4fbc-a263-682622774d68', 'e33041cc-39be-4e7f-a83c-a2c1c09174c6', 1, '{"sections":[{"kind":"safe","heading":"lo: length of each end zone","items":["Largest of: column depth h","1/6 of the clear height","450 mm"]},{"kind":"safe","heading":"Hoop spacing inside lo","items":["Smallest of: 1/4 of the least column dimension","6 × smallest longitudinal bar diameter","so = 100 + (350 − hx)/3 mm, kept between 100 and 150 mm"]},{"kind":"avoid","heading":"Common site errors","items":["Uniform spacing all the way up (no tight end zones)","First hoop too far from the beam/slab face","90° hooks instead of 135° seismic hooks"]},{"kind":"list","heading":"Terms","items":["hx: max center-to-center spacing of laterally supported bars","db: diameter of the longitudinal bar"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"column","hoops":"confined-ends","zones":[{"h":0.2,"status":"confine","label":"lo, tight hoops"},{"h":0.6,"status":"neutral"},{"h":0.2,"status":"confine","label":"lo, tight hoops"}],"dims":["lo","s ≤ 6db, 150","lo"],"caption":"SMF column: confinement zones at both ends"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
