insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('898a2a64-b8be-4faf-abde-af65d4b21672', '2e7b1393-2414-4809-b1d0-a7c23164e0a4', 1, '{"sections":[{"kind":"safe","heading":"Inside the 2h hoop zone","items":["First hoop ≤ 50 mm from the column face","Spacing ≤ smallest of d/4, 6 × smallest main bar diameter, 150 mm","Closed hoops with 135° seismic hooks"]},{"kind":"safe","heading":"Outside the hoop zone","items":["Stirrups with seismic hooks at ≤ d/2"]},{"kind":"avoid","heading":"Common site errors","items":["Starting the stirrups at the old ''d/2 from face'' habit","Open U-stirrups in the hoop zone","Lap splices inside the hoop zone (see the beam splice card)"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"span","member":"beam","support":"column","bands":"single","zones":[{"w":0.16,"status":"confine"},{"w":0.68,"status":"neutral"},{"w":0.16,"status":"confine"}],"dims":["2h","stirrups ≤ d/2","2h"],"spanLabel":"h = overall beam depth · d = effective depth","caption":"SMF beam: hoop zones at both ends"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
