insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'e979e9f2-f403-4953-8f2e-5b36077c93bb', 'practice', 'Construction joints: beams', 'construction-joints-beams', id, 'Where to stop a beam pour: middle third, vertical, bars running through.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('2bbddbdb-b62b-4c28-a773-a4734a983ecd', 'e979e9f2-f403-4953-8f2e-5b36077c93bb', 1, '{"sections":[{"kind":"safe","heading":"Safe to stop the pour","items":["Middle third of the span: lowest shear","Vertical joint with bars running through unbroken","Girders: offset at least 2 × the width of the beam framing in"]},{"kind":"avoid","heading":"Avoid","items":["Near the supports: highest shear, never at the column face","Horizontal joints in the beam: cast beam and slab together"]},{"kind":"list","heading":"Before the next pour","items":["Clean the joint and remove laitance","Roughen the surface","Wet it, but no standing water"]},{"kind":"text","heading":"Note","text":"Joint locations shown on the drawings or approved by the engineer govern. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"span","member":"beam","support":"column","bands":"single","zones":[{"w":0.3333333333333333,"status":"avoid"},{"w":0.3333333333333333,"status":"safe"},{"w":0.3333333333333333,"status":"avoid"}],"dims":["L/3","L/3","L/3"],"spanLabel":"L = clear span, face to face of columns","joint":{"at":0.5,"label":"Vertical joint, square to the beam"},"diagram":"shear","caption":"Beam construction joint: middle third only"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
