insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'd45b523d-c5e0-4c87-8490-8e0927fc1d16', 'practice', 'Construction joints: slabs', 'construction-joints-slabs', id, 'Where to stop a slab pour, and how to prepare it for the next one.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('f239fa41-205f-40b5-8e85-e9dd1b40362e', 'd45b523d-c5e0-4c87-8490-8e0927fc1d16', 1, '{"sections":[{"kind":"safe","heading":"Safe to stop the pour","items":["Middle third of the slab span","Straight vertical stop-end board, bars passing through","Plan pour breaks so beams and the slab they support are cast together"]},{"kind":"avoid","heading":"Avoid","items":["Directly over or next to a supporting beam","Feather-edged or sloping joints","Stopping in the middle of a beam''s width"]},{"kind":"list","heading":"Before the next pour","items":["Remove laitance, roughen, clean","Wet the joint with no ponding","Check that bars are not displaced at the stop-end"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"span","member":"slab","support":"beam","bands":"single","zones":[{"w":0.3333333333333333,"status":"avoid"},{"w":0.3333333333333333,"status":"safe"},{"w":0.3333333333333333,"status":"avoid"}],"dims":["L/3","L/3","L/3"],"spanLabel":"L = slab span between supporting beams","joint":{"at":0.5,"label":"Vertical stop-end"},"diagram":"shear","caption":"Slab construction joint: middle third"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
insert into public.entry_clause_refs (entry_id, clause_id, note) values ('d45b523d-c5e0-4c87-8490-8e0927fc1d16', '6419620a-2e79-4f86-bff0-f2e83335848a', 'Middle third · ACI 318-14 §26.5.6');
