insert into public.entries (id, module, title, slug, specialization_id, summary, status) select '42b5e2aa-d8f2-47bb-a4f5-9df39ba851d9', 'practice', 'Concrete cover: cast-in-place', 'concrete-cover-cast-in-place', id, 'Minimum cover by exposure and member, measured to the outermost steel.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('bbb803af-285f-43f2-84d1-49ce98185b9d', '42b5e2aa-d8f2-47bb-a4f5-9df39ba851d9', 1, '{"sections":[{"kind":"list","heading":"Minimum specified cover (cast-in-place, nonprestressed)","items":["Cast against and permanently in contact with earth: 75 mm","Exposed to weather or in contact with ground, 20–57 mm bars: 50 mm","Exposed to weather or in contact with ground, 16 mm bars and smaller: 40 mm","Not exposed, slabs/joists/walls, 43–57 mm bars: 40 mm","Not exposed, slabs/joists/walls, 36 mm bars and smaller: 20 mm","Not exposed, beams/columns/pedestals (main bars, stirrups, ties, hoops): 40 mm"]},{"kind":"safe","heading":"Do","items":["Use concrete or plastic spacers sized for the required cover","Measure cover to the stirrup/tie","Add cover for coastal/aggressive exposure if the specs require it"]},{"kind":"avoid","heading":"Avoid","items":["Stone, wood or CHB pieces as spacers","Footing bars sitting on soil or lean concrete without spacers","Measuring cover to the main bar"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"section","shape":"beam","b":300,"h":500,"barsTop":2,"barsBottom":3,"callouts":[{"kind":"cover-bottom","label":"Cover to stirrup, not main bar"},{"kind":"cover-side","label":"Side cover: same rule"}],"caption":"Beam section: cover measured to the stirrup"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
