insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'e1874ea0-4702-4fb7-9bad-c6fa0aa4667b', 'practice', 'Minimum clear spacing of bars', 'minimum-clear-spacing-of-bars', id, 'How close bars can be: concrete must flow and coarse aggregate must pass.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('10906882-82a1-4f09-b26e-a0b07fa463ed', 'e1874ea0-4702-4fb7-9bad-c6fa0aa4667b', 1, '{"sections":[{"kind":"safe","heading":"Beams and slabs","items":["Clear spacing in a layer ≥ largest of 25 mm, db, 4/3 × max aggregate","Second layer directly above the first, ≥ 25 mm clear between layers"]},{"kind":"safe","heading":"Columns","items":["Clear spacing between longitudinal bars ≥ largest of 40 mm, 1.5db, 4/3 × max aggregate","Check at lap splices, where bars are doubled"]},{"kind":"avoid","heading":"Avoid","items":["Bundling bars at laps so that spacing drops below the minimum","Using 3/4\" gravel in congested joints without checking 4/3 × aggregate"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, '{"type":"section","shape":"beam","b":350,"h":500,"barsTop":2,"barsBottom":4,"callouts":[{"kind":"clear-spacing","label":"≥ max(25 mm, db, 4/3 × agg.)"},{"kind":"cover-bottom","label":"Cover per cover card"}],"caption":"Beam section: clear spacing between bars"}'::jsonb, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
