insert into public.entries (id, module, title, slug, specialization_id, summary, status) select '6f8059aa-7769-452f-9465-efaea01ab692', 'practice', 'Standard hooks and bend diameters', 'standard-hooks-and-bend-diameters', id, '90°, 135° and 180° hook extensions and minimum bend diameters for bars, stirrups and ties.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('3f85eee1-ca76-4b04-bdd7-4d01b0729070', '6f8059aa-7769-452f-9465-efaea01ab692', 1, '{"sections":[{"kind":"list","heading":"Development hooks (main bars)","items":["90° hook: straight extension 12db","180° hook: extension ≥ 4db and ≥ 65 mm","Min. inside bend diameter: 6db (10–25 mm), 8db (28–36 mm), 10db (43–57 mm)"]},{"kind":"list","heading":"Stirrups and ties","items":["90° hook: 6db for 16 mm and smaller; 12db for 20–25 mm","135° hook: 6db for 25 mm and smaller","Min. inside bend diameter for 16 mm and smaller: 4db"]},{"kind":"safe","heading":"Seismic hooks (hoops and crossties)","items":["135° bend (90° allowed only for circular hoops)","Extension ≥ larger of 6db and 75 mm, engaging the longitudinal bar"]},{"kind":"avoid","heading":"Avoid","items":["Bending with a pipe over a nail: bend diameters too tight, cracks at the bend","Heating bars to bend them","Re-straightening bent bars without the engineer''s approval"]},{"kind":"text","heading":"Note","text":"A hook diagram will be added when the diagram engine gets a hook renderer. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, null, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
