insert into public.entries (id, module, title, slug, specialization_id, summary, status) select 'fbb433f4-03cb-4ba2-8f55-abc955a5ee63', 'practice', 'Curing of concrete', 'curing-of-concrete', id, 'Keep it wet and warm: minimum curing periods and site methods for PH conditions.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('9499c8dd-55ef-492a-bfad-90adac9a4a01', 'fbb433f4-03cb-4ba2-8f55-abc955a5ee63', 1, '{"sections":[{"kind":"safe","heading":"Minimum period","items":["Normal concrete: keep moist and above 10 °C for at least 7 days","High-early-strength concrete: at least 3 days","Start as soon as the surface will not be marred"]},{"kind":"safe","heading":"Site methods","items":["Ponding on slabs","Wet burlap or sacks kept continuously wet","Membrane curing compound applied right after finishing","Leave formwork on columns/beam sides longer in hot, windy weather"]},{"kind":"avoid","heading":"Avoid","items":["Wetting once a day and letting it dry in between","Leaving fresh slabs exposed to midday sun and wind","Loading the slab with materials during early curing"]},{"kind":"text","heading":"Note","text":"Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, null, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
