insert into public.entries (id, module, title, slug, specialization_id, summary, status) select '025cdf5c-74e9-4ab9-820f-6f086b5de760', 'practice', 'Concrete strength sampling and acceptance', 'concrete-strength-sampling-and-acceptance', id, 'How many cylinder sets to take and when the results pass.', 'review' from public.specializations where slug = 'concrete';
insert into public.entry_revisions (id, entry_id, rev_no, body, diagram, change_note, code_edition) values ('4a3d2279-63f7-4b5f-aebe-732e9d8c226d', '025cdf5c-74e9-4ab9-820f-6f086b5de760', 1, '{"sections":[{"kind":"list","heading":"Sampling frequency (per class of concrete), at least","items":["Once per day of placement","Once per 110 m³ placed","Once per 460 m² of slab or wall surface"]},{"kind":"list","heading":"One strength test","items":["Average of two 150×300 mm or three 100×200 mm cylinders","Tested at the specified age (usually 28 days)"]},{"kind":"safe","heading":"Acceptance (standard-cured cylinders)","items":["Every average of 3 consecutive tests ≥ f''c","No single test below f''c − 3.5 MPa (f''c ≤ 35 MPa) or below 0.90 f''c (f''c > 35 MPa)"]},{"kind":"avoid","heading":"Avoid","items":["Cylinders left in the sun or moved during the first 24 h","Sampling only from the first truck","Adding water at site after sampling"]},{"kind":"text","heading":"Note","text":"DPWH projects may require more frequent sampling per the Blue Book and contract specs. Clause numbers follow the NSCP 2015 ↔ ACI 318-14 numbering. Check each value against your own NSCP copy before marking reviewed."}]}'::jsonb, null, 'Initial draft (v0.2.0): needs review', 'NSCP 2015');
