insert into public.releases (version, batch_name, notes_md, released_at) values ('v0.2.0','Diagram engine + Concrete Practices I', E'- SVG diagram engine: span, column and section renderers driven by JSON specs\n- 12 Concrete Practice cards (splice zones, construction joints, cover, spacing, hooks, confinement, curing, testing) as drafts for review\n- NSCP 2015 clause index: 11 clauses with ACI 318-14 equivalents\n- Admin: Mark reviewed & publish button on each entry', now());
